package main

// Original independent ZIP and alpha 0.4 FAW fixture bytes retained unchanged.
// Generated only into test-owned temporary directories; never part of the EXE.
import (
	"encoding/base64"
	"fmt"
	"os"
	"path/filepath"
	"testing"
)

var encodedArchiveFixtures = map[string]string{
	"sample-faw4.faw":      "",
	"external-bzip2.zip":   "",
	"external-deflate.zip": "",
	"external-store.zip":   "",
}

func archiveFixtureBytes(name string) ([]byte, error) {
	s, ok := encodedArchiveFixtures[name]
	if !ok {
		return nil, fmt.Errorf("unknown fixture: %s", name)
	}
	return base64.StdEncoding.DecodeString(s)
}
func archiveFixture(t *testing.T, name string) string {
	t.Helper()
	b, e := archiveFixtureBytes(name)
	if e != nil {
		t.Fatal(e)
	}
	p := filepath.Join(t.TempDir(), name)
	if e = os.WriteFile(p, b, 0600); e != nil {
		t.Fatal(e)
	}
	return p
}
